// Package cloudformation holds the CloudFormation templates of the IAM
// roles the platform assumes in a tenant AWS account, which the API
// server serves (Mount) for tenants to create the role's stack with, and
// of the two roles of the platform's own (management) account it runs as
// (management.go).
//
// The templates are generated by scripts/generate.py (make cf-generate)
// into templates/ and embedded here; do not edit them by hand.
package cloudformation

import (
	"embed"
	"fmt"
	"slices"
	"strings"
)

//go:embed templates/*.template.yaml
var templates embed.FS

// Platform is the prefix of every role, policy and stack name.
const Platform = "cluster-vending"

// ParameterManagementRoleARN is the templates' parameter of the role the
// tenant role trusts (the platform's management role).
const ParameterManagementRoleARN = "ManagementRoleArn"

// ParameterServerPrincipalARN is the templates' parameter of the API
// server's principal, which the role trusts next to the management role so
// that the server can read the cluster results buckets (read-only; its
// session is limited to that). Empty: the server has no AWS access and the
// role trusts the management role only. ConditionHasServerPrincipal is the
// template condition on it.
const (
	ParameterServerPrincipalARN = "ServerPrincipalArn"
	ConditionHasServerPrincipal = "HasServerPrincipalArn"
)

// ParameterRoleName is the templates' parameter of the role's name (and
// its policies' prefix): RoleName(role) by default, or
// cluster-vending-<anything>-<role> for a stack of its own.
const ParameterRoleName = "RoleName"

// ParameterExternalID is the templates' parameter of the account's
// external ID (NoEcho): set, the role's trust requires the management role
// to pass it (sts:ExternalId); empty, none (accounts onboarded before
// external IDs). ConditionHasExternalID is the template condition on it.
const (
	ParameterExternalID    = "ExternalId"
	ConditionHasExternalID = "HasExternalId"
)

// ParameterCreateSpotServiceLinkedRole is the provisioner template's
// parameter that makes its stack create the account's EC2 Spot
// service-linked role (AWSServiceRoleForEC2Spot), which Karpenter's Spot
// nodes need: "true" or "false" (the default). CloudFormation cannot
// create a resource that exists, and an account that ever used Spot has
// this role, so it is off unless the account is known not to have it
// (aws iam get-role --role-name AWSServiceRoleForEC2Spot).
// ConditionCreateSpotServiceLinkedRole is the template condition on it.
const (
	ParameterCreateSpotServiceLinkedRole = "CreateSpotServiceLinkedRole"
	ConditionCreateSpotServiceLinkedRole = "CreateSpotServiceLinkedRole"
)

// maxRoleName is IAM's limit on a role's name.
const maxRoleName = 64

// DefaultRole is the role the controller needs today: it creates and
// deletes networks and clusters.
const DefaultRole = "provisioner"

// roles, each a superset of the one before (scripts/generate.py).
var roles = []string{"reader", "updater", "provisioner"}

// RoleName is the IAM role (and stack) name of a role.
func RoleName(role string) string { return Platform + "-" + role }

// RoleOf is the role whose template creates an IAM role of this name:
// cluster-vending-<role> or cluster-vending-<anything>-<role>; "" for a
// name none of the templates creates (or longer than IAM allows).
func RoleOf(name string) string {
	rest, ok := strings.CutPrefix(name, Platform+"-")
	if !ok || len(name) > maxRoleName {
		return ""
	}
	parts := strings.Split(rest, "-")
	if role := parts[len(parts)-1]; slices.Contains(roles, role) && !slices.Contains(parts[:len(parts)-1], "") {
		return role
	}
	return ""
}

// fileName is the role's template in templates/.
func fileName(role string) string { return RoleName(role) + "-role.template.yaml" }

// Template is the CloudFormation template of a role.
func Template(role string) ([]byte, error) {
	if !slices.Contains(roles, role) {
		return nil, fmt.Errorf("unknown role %q: reader, updater or provisioner", role)
	}
	return templates.ReadFile("templates/" + fileName(role))
}
